package com.jclicktv.appvault;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.view.*;
public class MainActivity extends Activity {
 WebView web; DownloadManager dm; long active=-1; Handler h=new Handler(Looper.getMainLooper()); ProgressDialog progress;
 final String home="https://jclicktv.com/apps1/?tv=1";
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894);web=new WebView(this);setContentView(web);web.setBackgroundColor(0xff101010);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);
 web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !"https".equals(r.getUrl().getScheme())||!"jclicktv.com".equalsIgnoreCase(r.getUrl().getHost());}public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())new AlertDialog.Builder(MainActivity.this).setMessage("Connection failed").setPositiveButton("Retry",(d,w)->web.loadUrl(home)).setNegativeButton("Close",(d,w)->finish()).show();}});
 dm=(DownloadManager)getSystemService(DOWNLOAD_SERVICE);web.setDownloadListener((url,ua,cd,mime,len)->download(url,ua));web.loadUrl(home);web.requestFocus();}
 void download(String url,String ua){Uri u=Uri.parse(url);if(!"https".equals(u.getScheme())||!"jclicktv.com".equalsIgnoreCase(u.getHost()))return;if(active!=-1)return;try{DownloadManager.Request r=new DownloadManager.Request(u);r.setTitle("App Vault download");r.setMimeType("application/vnd.android.package-archive");r.addRequestHeader("User-Agent",ua);String cookie=CookieManager.getInstance().getCookie(url);if(cookie!=null)r.addRequestHeader("Cookie",cookie);r.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);r.setDestinationInExternalFilesDir(this,Environment.DIRECTORY_DOWNLOADS,"app-"+System.currentTimeMillis()+".apk");active=dm.enqueue(r);progress=new ProgressDialog(this);progress.setTitle("Downloading APK");progress.setProgressStyle(ProgressDialog.STYLE_HORIZONTAL);progress.setMax(100);progress.setCancelable(false);progress.setButton(DialogInterface.BUTTON_NEGATIVE,"Cancel",(d,w)->{dm.remove(active);active=-1;});progress.show();h.post(poll);}catch(Exception e){active=-1;new AlertDialog.Builder(this).setMessage("Unable to start download").setPositiveButton("OK",null).show();}}
 Runnable poll=new Runnable(){public void run(){if(active==-1)return;try(android.database.Cursor c=dm.query(new DownloadManager.Query().setFilterById(active))){if(c!=null&&c.moveToFirst()){int s=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));long total=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_TOTAL_SIZE_BYTES));long done=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR));if(total>0)progress.setProgress((int)(100*done/total));if(s==DownloadManager.STATUS_SUCCESSFUL){Uri uri=dm.getUriForDownloadedFile(active);active=-1;progress.dismiss();install(uri);return;}if(s==DownloadManager.STATUS_FAILED){active=-1;progress.dismiss();new AlertDialog.Builder(MainActivity.this).setMessage("Download failed").setPositiveButton("OK",null).show();return;}}}h.postDelayed(this,500);}};
 Uri pending;void install(Uri uri){pending=uri;if(Build.VERSION.SDK_INT>=26&&!getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(this).setMessage("Allow App Vault to install unknown apps, then return.").setPositiveButton("Settings",(d,w)->startActivityForResult(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())),7)).setNegativeButton("Cancel",null).show();return;}try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(uri,"application/vnd.android.package-archive");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);}catch(Exception e){new AlertDialog.Builder(this).setMessage("Package installer unavailable").setPositiveButton("OK",null).show();}}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==7&&pending!=null&&Build.VERSION.SDK_INT>=26&&getPackageManager().canRequestPackageInstalls())install(pending);}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}